style.css:
@-moz-document domain("netflix.com") {
/* ===== 1. Font ===== */
    * {
        font-family: "Monotype Corsiva", cursive !important;
    }

    /* ===== 2. Background Image (fantasy tone) ===== */
    body::before {
        content: '';
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        background-image: url("https://i.postimg.cc/DZxqnSLg/764a0a214cd8d077fce61134b25bfee5.jpg");
        background-size: cover;
        background-position: center;
        opacity: 0.08;
        z-index: -1;
        pointer-events: none;
    }

    /* ===== 3. Logo Area Character ===== */
    .our-story-logo::after {
        content: '';
        position: absolute;
        top: 10px;
        left: 120px;
        width: 50px;
        height: 50px;
        background-image: url("https://i.postimg.cc/j2WJTZsx/430861.jpg");
        background-size: contain;
        background-repeat: no-repeat;
        z-index: 1000;
        pointer-events: none;
    }

    /* ===== 4. Play Button Icon Character ===== */
    .previewModal--player-container button.playLink::after,
    .button-nfplayerPlay::after {
        content: '';
        display: inline-block;
        width: 24px;
        height: 24px;
        background-image: url("https://i.postimg.cc/NFrLSF4L/6b6f04eececcf6fdee35b67c4079c0e7.jpg");
        background-size: cover;
        margin-left: 6px;
        vertical-align: middle;
    }

    /* ===== 5. "My List" Button Decoration ===== */
    button[data-uia="add-to-my-list-button"]::after {
        content: '';
        display: inline-block;
        width: 20px;
        height: 20px;
        background-image: url("https://i.postimg.cc/cJ4Rj78H/8181571cc55945b53fc2e26121dd2a52.png");
        background-size: contain;
        margin-left: 6px;
        vertical-align: middle;
    }

    /* ===== 6. Corner Character (bottom-right) ===== */
    body::after {
        content: '';
        position: fixed;
        bottom: 20px;
        right: 20px;
        width: 80px;
        height: 80px;
        background-image: url("https://i.postimg.cc/15qNYCCM/message-Image-1739882637472.jpg");
        background-size: contain;
        background-repeat: no-repeat;
        z-index: 10000;
        pointer-events: none;
    }

    /* ===== 7. Theme Colors ===== */
    html, body,
    .mainView,
    .nm-content-horizontal-row,
    .lolomo,
    .previewModal--player-container,
    .nf-player-container {
        background-color: #001a33 !important;
        color: #e0f7ff !important;
    }

    a, button {
        color: #ffd700 !important;
    }

    ::selection {
        background-color: #1c3aa9 !important;
        color: white;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #ffd700 !important;
    }

    /* ===== 8. Scrubber Handle Character Icon ===== */
    .scrubber-head::after {
        content: '';
        display: block;
        width: 40px;
        height: 40px;
        background-image: url("https://i.postimg.cc/15qNYCCM/message-Image-1739882637472.jpg");
        background-size: contain;
        background-repeat: no-repeat;
        position: absolute;
        top: -25px;
        left: -10px;
        z-index: 10;
        pointer-events: none;
    }

    /* ===== 9. Player Bar Character Decoration (left of progress bar) ===== */
    .scrubber-bar::before {
        content: '';
        display: block;
        position: absolute;
        bottom: -50px;
        left: 0;
        width: 60px;
        height: 60px;
        background-image: url("https://i.postimg.cc/cJ4Rj78H/8181571cc55945b53fc2e26121dd2a52.png");
        background-size: contain;
        background-repeat: no-repeat;
        z-index: 9;
        pointer-events: none;
    }
}
